class MemoryAllocator:
    def __init__(self, size):
        self.size = size
        self.memory_block = [None] * size
        self.pointer = 0

    def allocate(self, block_size):
        if self.pointer + block_size > self.size:
            raise MemoryError("Not enough memory to allocate")
        start_index = self.pointer
        self.pointer += block_size
        return start_index

    def deallocate(self, start_index, block_size):
        for i in range(start_index, start_index + block_size):
            self.memory_block[i] = None
        self.pointer = max(0, self.pointer - block_size)

# Example usage:
allocator = MemoryAllocator(100)
ptr = allocator.allocate(10)
print(f"Allocated block at pointer: {ptr}")

