import ctypes

class Person:
    def __init__(self, name, age):
        self.name = name
        self.age = age

def allocate_memory():
    # Allocate memory block of size sizeof(Person)
    size = ctypes.sizeof(Person)
    ptr = ctypes.pythonapi.PyMem_Malloc(size)
    return ptr

def free_memory(p):
    # Free the memory block referenced by pointer p
    if p:
        ctypes.pythonapi.PyMem_Free(p)

