class MemoryAllocator:
    def __init__(self, total_size):
        self.total_size = total_size
        self.memory = [None] * total_size  # 0 = free, 1 = allocated
        self.pointers = {}  # block_id -> start_index

    def allocate(self, size):
        if size <= 0:
            return None

        # Find a contiguous free block of required size
        start = -1
        count = 0
        for i in range(self.total_size):
            if self.memory[i] is None:
                if count == 0:
                    start = i
                count += 1
                if count == size:
                    # Allocate the block
                    for j in range(start, start + size):
                        self.memory[j] = 1
                    block_id = id(self)  # Simple unique ID
                    self.pointers[block_id] = start
                    return start
            else:
                count = 0
                start = -1
        return None  # No suitable block found

    def deallocate(self, pointer):
        if pointer is None:
            return

        # Find the block with this pointer
        block_id = None
        for bid, start in self.pointers.items():
            if start == pointer:
                block_id = bid

