class Person:
    def __init__(self, name, age, address):
        self.name = name
        self.age = age
        self.address = address

    @staticmethod
    def allocate_memory(name, age, address):
        """
        Mô phỏng phương thức cấp phát bộ nhớ như trong C/C++.
        Trả về một đối tượng Person (tương đương với con trỏ đến khối bộ nhớ).
        """
        return Person(name, age, address)

# Ví dụ sử dụng
person_ptr = Person.allocate_memory("Alice", 30, "123 Main St")
print(f"Name: {person_ptr.name}, Age: {person_ptr.age}, Address: {person_ptr.address}")
